export interface BuildingApprovalsSummary {
  latest_monthly: number
  annual_run_rate: number
  accord_target: number
  gap_to_target: number
  pct_of_target: number
  yoy_change_pct: number
  latest_date: string
}

export function getBuildingApprovalsSummary(): BuildingApprovalsSummary {
  const latest = BUILDING_APPROVALS[BUILDING_APPROVALS.length - 1]

  // Annual run rate — trailing 12-month sum (ABS standard methodology).
  // Sums the most recent 12 months of actual approvals data.
  // This is stable across seasonal variation and directly matches what ABS
  // publishes as the annual total in their headline release.
  const last12 = BUILDING_APPROVALS.slice(-12)
  const annual_run_rate = last12.reduce((sum, r) => sum + r.total_aus, 0)

  const accord_target = 240000

  // Supply gap — how many dwellings per year Australia is short of the Accord target.
  const gap_to_target = accord_target - annual_run_rate

  // % of target — what share of the required 240,000/yr is currently being delivered.
  const pct_of_target = Math.round((annual_run_rate / accord_target) * 100)

  // YoY — latest month vs the same calendar month 12 months prior.
  const twelveMonthsAgo = BUILDING_APPROVALS[BUILDING_APPROVALS.length - 13]
  const yoy_change_pct =
    Math.round(
      ((latest.total_aus - twelveMonthsAgo.total_aus) / twelveMonthsAgo.total_aus) *
        100 * 10
    ) / 10

  return {
    latest_monthly: latest.total_aus,
    annual_run_rate,
    accord_target,
    gap_to_target,
    pct_of_target,
    yoy_change_pct,
    latest_date: latest.date,
  }
}
